#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    // Ao cortar na altura h:
    //   - o Trecho abaixo do corte forma sempre 1 peca (as bases assentam na mesma linha);
    //   - cada "run" maximal de retangulos consecutivos com altura > h forma 1 peca acima.
    // Logo, pedacos(h) = 1 + numero de "inicios de run": indices i com A[i] > h e (i == 0 ou A[i-1] <= h).
    // O inicio i (i > 0) fica ativo para h em [A[i-1], A[i]); o inicio 0 fica ativo para h em [0, A[0]).
    // Se A[i-1] >= A[i], o inicio i nunca fica ativo (intervalo vazio).
    // A resposta e 1 + maximo de intervalos contendo algum h (varredura de eventos, aplicando
    // todos os deltas de um mesmo valor antes de registrar, o que trata corretamente extremos abertos/fechados).

    vector<pair<long long,int>> ev;
    ev.reserve(2u * (size_t)n);

    ev.push_back({0LL, +1});
    ev.push_back({a[0], -1});

    for (int i = 1; i < n; ++i){
        if (a[i-1] < a[i]){
            ev.push_back({a[i-1], +1});
            ev.push_back({a[i], -1});
        }
    }

    sort(ev.begin(), ev.end(),
         [](const pair<long long,int>& x, const pair<long long,int>& y){
             return x.first < y.first;
         });

    long long cnt = 0, best = 0;
    size_t i = 0;
    while (i < ev.size()){
        long long v = ev[i].first;
        while (i < ev.size() && ev[i].first == v){
            cnt += ev[i].second;
            ++i;
        }
        if (cnt > best) best = cnt;
    }

    cout << (best + 1) << "\n";
    return 0;
}
